// ================= PART 6: MULTI-LEVEL HANDBOOK (6x4), ABBREVIATION SEARCH & BOOTSTRAP =================

const HANDBOOK_TABS = [
  {
    "title": "1. Kiến Trúc CAN Stack & CanIf",
    "subs": [
      {
        "title": "1.1 Vị Trí & Vai Trò ECU Abstraction",
        "html": "\n<div class=\"hb-card\">\n  <h3>1.1 CanIf Trong Kiến Trúc Phân Tầng AUTOSAR Classic (ModuleId = 60)</h3>\n  <p><b>CanIf (CAN Interface)</b> nằm ở tầng <b>ECU Abstraction Layer</b>, đóng vai trò cầu nối chuẩn hóa giữa các tầng trên (<code>PduR</code>, <code>CanTp</code>, <code>CanNm</code>, <code>CanTSyn</code>, <code>J1939Nm</code>, <code>CDD</code>) với tầng phần cứng bên dưới (<code>CanDrv</code> MCAL và <code>CanTrcv</code>).</p>\n  <svg class=\"hb-svg\" viewBox=\"0 0 820 380\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"hbArr\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"currentColor\" /></marker></defs><rect x=\"20\" y=\"16\" width=\"220\" height=\"48\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--pri)\" stroke-width=\"1.6\" /><text x=\"130.0\" y=\"36.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">SWC_App &amp; SWC_Diag</text><text x=\"130.0\" y=\"52.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Rte_Write() / Dem / UDS</text><rect x=\"290\" y=\"16\" width=\"230\" height=\"48\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--pur)\" stroke-width=\"1.6\" /><text x=\"405.0\" y=\"36.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">EcuM &amp; CanSM / ComM / BswM</text><text x=\"405.0\" y=\"52.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">SetCtrlMode / SetPduMode / Wakeup</text><rect x=\"570\" y=\"16\" width=\"230\" height=\"48\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--err)\" stroke-width=\"1.6\" /><text x=\"685.0\" y=\"36.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">DET &amp; IdsM (ModuleId 60)</text><text x=\"685.0\" y=\"52.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">0x32 / 0x33 / Security Events</text><rect x=\"180\" y=\"92\" width=\"460\" height=\"52\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--cyan)\" stroke-width=\"1.6\" /><text x=\"410.0\" y=\"114.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">Upper Layers: PduR / Com | CanTp | CanNm | CanTSyn | SecOC | CDD</text><text x=\"410.0\" y=\"130.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">CanIf_Transmit()  &lt;---&gt;  &lt;User&gt;_RxIndication / &lt;User&gt;_TxConfirmation</text><rect x=\"150\" y=\"178\" width=\"520\" height=\"62\" rx=\"8\" fill=\"var(--pri-bg)\" stroke=\"var(--pri)\" stroke-width=\"1.6\" /><text x=\"410.0\" y=\"205.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">CanIf (ECU Abstraction Layer — SWS_CanIf R23-11)</text><text x=\"410.0\" y=\"221.0\" text-anchor=\"middle\" fill=\"var(--txt)\" font-size=\"10\" font-weight=\"500\">HOH Map (FullCAN/BasicCAN) | CanIfTxBuffer Queue | SwFilter &amp; DLC Check | PduMode Gate</text><rect x=\"60\" y=\"276\" width=\"310\" height=\"52\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--ok)\" stroke-width=\"1.6\" /><text x=\"215.0\" y=\"298.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">CanDrv (MCAL CAN Controller)</text><text x=\"215.0\" y=\"314.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Can_Write(HTH) | RxInd / TxConfirm / BusOff</text><rect x=\"450\" y=\"276\" width=\"310\" height=\"52\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--cyan)\" stroke-width=\"1.6\" /><text x=\"605.0\" y=\"298.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">CanTrcv (TJA1145 / TJA1043)</text><text x=\"605.0\" y=\"314.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">SetOpMode / CheckWakeup / WUF PN</text><rect x=\"170\" y=\"344\" width=\"480\" height=\"22\" rx=\"10\" fill=\"var(--panel-3)\" stroke=\"var(--pri)\" stroke-width=\"1.2\" /><text x=\"410.0\" y=\"358.5\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"10\" font-weight=\"700\">CAN / CAN-FD Physical Bus (CAN_H / CAN_L · Arbitration 500k + Data 2M/5M)</text><line x1=\"130\" y1=\"64\" x2=\"240\" y2=\"92\" stroke=\"var(--pri)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--pri)\" /><text x=\"155.0\" y=\"80.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"9.5\" font-weight=\"700\">RTE / I-PDU</text><line x1=\"405\" y1=\"64\" x2=\"405\" y2=\"178\" stroke=\"var(--pur)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--pur)\" /><text x=\"468.0\" y=\"166.0\" text-anchor=\"middle\" fill=\"var(--pur)\" font-size=\"9.5\" font-weight=\"700\">Mode / CheckWakeup</text><line x1=\"410\" y1=\"144\" x2=\"410\" y2=\"178\" stroke=\"var(--cyan)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--cyan)\" /><text x=\"362.0\" y=\"164.0\" text-anchor=\"middle\" fill=\"var(--cyan)\" font-size=\"9.5\" font-weight=\"700\">Tx / Rx Cbk</text><line x1=\"570\" y1=\"209\" x2=\"685\" y2=\"64\" stroke=\"var(--err)\" stroke-width=\"1.8\" stroke-dasharray=\"4 3\" marker-end=\"url(#hbArr)\" style=\"color:var(--err)\" /><text x=\"662.0\" y=\"140.0\" text-anchor=\"middle\" fill=\"var(--err)\" font-size=\"9.5\" font-weight=\"700\">DET 0x32/33</text><line x1=\"290\" y1=\"240\" x2=\"215\" y2=\"276\" stroke=\"var(--ok)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--ok)\" /><text x=\"215.0\" y=\"256.0\" text-anchor=\"middle\" fill=\"var(--ok)\" font-size=\"9.5\" font-weight=\"700\">Can_Write()</text><line x1=\"530\" y1=\"240\" x2=\"605\" y2=\"276\" stroke=\"var(--cyan)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--cyan)\" /><text x=\"605.0\" y=\"256.0\" text-anchor=\"middle\" fill=\"var(--cyan)\" font-size=\"9.5\" font-weight=\"700\">Trcv SPI/Pin</text></svg>\n  <div class=\"hb-grid2\">\n    <div>\n      <h4>Tại sao phải tách CanIf khỏi CanDrv?</h4>\n      <ul>\n        <li><b>Phần cứng độc lập (HW Abstraction):</b> Tầng trên chỉ biết tới <code>PduIdType</code> (ID logic); CanIf ánh xạ ID đó sang <code>Can_HwHandleType</code> (HTH/HRH) của từng chip MCU khác nhau (Infineon AURIX TC3xx, NXP S32K3, Renesas RH850).</li>\n        <li><b>Không chứa giao thức hay đóng gói Signal:</b> CanIf chỉ xử lý nguyên khung <b>L-PDU</b> (tối đa 8B CAN 2.0 hoặc 64B CAN FD); việc giải mã Signal do <code>Com</code>, phân mảnh Multi-frame do <code>CanTp</code>, và State Machine mạng do <code>CanNm/CanSM</code>.</li>\n      </ul>\n    </div>\n    <div>\n      <h4>Luồng giao tiếp với từng nhóm module</h4>\n      <table class=\"tbl\">\n        <tr><th>Nhóm Module</th><th>Hướng tương tác với CanIf</th></tr>\n        <tr><td><b>PduR / CanTp / CanNm / CanTSyn</b></td><td>Gọi xuống <code>CanIf_Transmit()</code>; nhận callback <code>&lt;User&gt;_RxIndication</code>, <code>&lt;User&gt;_TxConfirmation</code>.</td></tr>\n        <tr><td><b>CanSM / BswM</b></td><td>Điều khiển <code>CanIf_SetControllerMode()</code>, <code>CanIf_SetPduMode()</code>, <code>CanIf_SetTrcvMode()</code>, <code>CanIf_SetBaudrate()</code>.</td></tr>\n        <tr><td><b>EcuM</b></td><td>Kiểm tra và xác thực đánh thức qua <code>CanIf_CheckWakeup()</code> &amp; <code>CanIf_CheckValidation()</code>.</td></tr>\n        <tr><td><b>CanDrv / CanTrcv</b></td><td>Nhận lệnh <code>Can_Write()</code>, <code>CanTrcv_SetOpMode()</code> và đẩy ngắt <code>RxIndication</code> / <code>TxConfirmation</code> / <code>BusOff</code> lên CanIf.</td></tr>\n      </table>\n    </div>\n  </div>\n</div>"
      },
      {
        "title": "1.2 Cấu Trúc 32-bit Can_IdType (SWS_Can_00416)",
        "html": "\n<div class=\"hb-card\">\n  <h3>1.2 Giải Mã Thanh Ghi 32-bit Can_IdType: Standard vs Extended &amp; CAN FD</h3>\n  <p>Thay vì truyền hai tham số tách rời (CAN ID và Frame Flag), AUTOSAR hợp nhất toàn bộ thông tin định danh và chuẩn khung truyền vào một số nguyên không dấu 32-bit duy nhất gọi là <code>Can_IdType</code>.</p>\n  <svg class=\"hb-svg\" viewBox=\"0 0 820 216\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"hbArr\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"currentColor\" /></marker></defs><rect x=\"20\" y=\"12\" width=\"780\" height=\"24\" rx=\"10\" fill=\"var(--pri-bg)\" stroke=\"var(--pri)\" stroke-width=\"1.2\" /><text x=\"410.0\" y=\"27.5\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"10\" font-weight=\"700\">Cấu trúc chuẩn uint32 Can_IdType theo SWS_Can_00416 (AUTOSAR R23-11)</text><rect x=\"20\" y=\"50\" width=\"120\" height=\"68\" rx=\"8\" fill=\"var(--pur-bg)\" stroke=\"var(--pur)\" stroke-width=\"1.6\" /><text x=\"80.0\" y=\"72.0\" text-anchor=\"middle\" fill=\"var(--pur)\" font-size=\"12\" font-weight=\"800\">Bit 31 (MSB)</text><text x=\"80.0\" y=\"88.0\" text-anchor=\"middle\" fill=\"var(--txt)\" font-size=\"10\" font-weight=\"500\">EXT_ID Flag</text><text x=\"80.0\" y=\"104.0\" text-anchor=\"middle\" fill=\"var(--mut)\" font-size=\"10\" font-weight=\"500\">0=11b | 1=29b</text><rect x=\"150\" y=\"50\" width=\"120\" height=\"68\" rx=\"8\" fill=\"var(--cyan-bg)\" stroke=\"var(--cyan)\" stroke-width=\"1.6\" /><text x=\"210.0\" y=\"72.0\" text-anchor=\"middle\" fill=\"var(--cyan)\" font-size=\"12\" font-weight=\"800\">Bit 30</text><text x=\"210.0\" y=\"88.0\" text-anchor=\"middle\" fill=\"var(--txt)\" font-size=\"10\" font-weight=\"500\">FD_MODE Flag</text><text x=\"210.0\" y=\"104.0\" text-anchor=\"middle\" fill=\"var(--mut)\" font-size=\"10\" font-weight=\"500\">0=CAN | 1=FD</text><rect x=\"280\" y=\"50\" width=\"95\" height=\"68\" rx=\"8\" fill=\"var(--panel-3)\" stroke=\"var(--bdr)\" stroke-width=\"1.6\" /><text x=\"327.5\" y=\"72.0\" text-anchor=\"middle\" fill=\"var(--mut)\" font-size=\"12\" font-weight=\"800\">Bit 29</text><text x=\"327.5\" y=\"88.0\" text-anchor=\"middle\" fill=\"var(--txt)\" font-size=\"10\" font-weight=\"500\">Reserved</text><text x=\"327.5\" y=\"104.0\" text-anchor=\"middle\" fill=\"var(--mut)\" font-size=\"10\" font-weight=\"500\">Luôn = 0</text><rect x=\"385\" y=\"50\" width=\"415\" height=\"68\" rx=\"8\" fill=\"var(--ok-bg)\" stroke=\"var(--ok)\" stroke-width=\"1.6\" /><text x=\"592.5\" y=\"72.0\" text-anchor=\"middle\" fill=\"var(--ok)\" font-size=\"12\" font-weight=\"800\">Bits 28 .. 0 (29 bits)</text><text x=\"592.5\" y=\"88.0\" text-anchor=\"middle\" fill=\"var(--txt)\" font-size=\"10\" font-weight=\"500\">Arbitration CAN Identifier (Standard: Bits 10..0 | Extended: Bits 28..0)</text><text x=\"592.5\" y=\"104.0\" text-anchor=\"middle\" fill=\"var(--mut)\" font-size=\"10\" font-weight=\"500\">Mask: 0x000007FF (Std) hoặc 0x1FFFFFFF (Ext)</text><rect x=\"20\" y=\"142\" width=\"250\" height=\"56\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--ok)\" stroke-width=\"1.6\" /><text x=\"145.0\" y=\"166.0\" text-anchor=\"middle\" fill=\"var(--ok)\" font-size=\"12\" font-weight=\"800\">0x00000100</text><text x=\"145.0\" y=\"182.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">B31=0, B30=0 -&gt; Std CAN 11-bit</text><rect x=\"285\" y=\"142\" width=\"250\" height=\"56\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--cyan)\" stroke-width=\"1.6\" /><text x=\"410.0\" y=\"166.0\" text-anchor=\"middle\" fill=\"var(--cyan)\" font-size=\"12\" font-weight=\"800\">0x40000120</text><text x=\"410.0\" y=\"182.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">B31=0, B30=1 -&gt; Std CAN FD 64B</text><rect x=\"550\" y=\"142\" width=\"250\" height=\"56\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--pur)\" stroke-width=\"1.6\" /><text x=\"675.0\" y=\"166.0\" text-anchor=\"middle\" fill=\"var(--pur)\" font-size=\"12\" font-weight=\"800\">0xD8FEF100</text><text x=\"675.0\" y=\"182.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">B31=1, B30=1 -&gt; Ext CAN FD 29-bit</text></svg>\n  <table class=\"tbl\">\n    <tr><th>Vị Trí Bit</th><th>Tên Cờ</th><th>Giá Trị &amp; Ý Nghĩa (SWS_Can_00416)</th></tr>\n    <tr><td class=\"mono\">Bit 31 (MSB)</td><td><b>EXT_ID Flag</b></td><td><code>0</code> = Standard CAN (11-bit ID 0x000..0x7FF); <code>1</code> = Extended CAN (29-bit ID, cộng mặt nạ <code>0x80000000</code>).</td></tr>\n    <tr><td class=\"mono\">Bit 30</td><td><b>FD_MODE Flag</b></td><td><code>0</code> = Classical CAN 2.0 (Max 8B); <code>1</code> = CAN FD Frame lên tới 64 Bytes (cộng mặt nạ <code>0x40000000</code>).</td></tr>\n    <tr><td class=\"mono\">Bit 29</td><td><b>Reserved</b></td><td>Luôn bằng <code>0</code> trong chuẩn AUTOSAR R23-11.</td></tr>\n    <tr><td class=\"mono\">Bits 28..0</td><td><b>CAN Identifier</b></td><td>Giá trị Arbitration ID thực sự truyền lên bus vật lý CAN_H / CAN_L.</td></tr>\n  </table>\n</div>"
      },
      {
        "title": "1.3 SWC, RTE & Bảo Vệ SchM ExclusiveArea",
        "html": "\n<div class=\"hb-card\">\n  <h3>1.3 Tương Tác Gián Tiếp SWC ↔ CanIf &amp; Vùng Găng SchM</h3>\n  <div class=\"hb-grid2\">\n    <div>\n      <h4>SWC KHÔNG bao giờ gọi trực tiếp CanIf</h4>\n      <p>Theo nguyên tắc phân tách AUTOSAR, Software Component (<code>SWC</code>) chỉ gọi API trừu tượng của <b>RTE</b> (ví dụ <code>Rte_Write_PpBrake_Torque()</code>). Sau đó <code>Com</code> gom tín hiệu vào I-PDU, đưa qua <code>PduR</code> định tuyến tới <code>CanIf_Transmit()</code>.</p>\n      <p>Tương tự, với chuyển trạng thái mạng, <code>SWC</code> xin chế độ qua <code>ComM_RequestComMode()</code> ➔ <code>CanSM</code> ➔ <code>CanIf_SetControllerMode()</code>.</p>\n    </div>\n    <div>\n      <h4>Tại sao CanIf cần SchM_Enter_CanIf_EXCLUSIVE_AREA_0?</h4>\n      <ul>\n        <li><b>Xung đột Task vs ISR:</b> Task 10ms đang gọi <code>CanIf_Transmit()</code> để chèn bản tin vào <code>CanIfTxBuffer</code>, đúng lúc đó ngắt cứng CAN ISR nhảy vào <code>CanIf_TxConfirmation()</code> để lấy phần tử đầu hàng đợi ra!</li>\n        <li>Nếu không khóa ngắt ngắn bằng <code>SchM_Enter/Exit_CanIf_EXCLUSIVE_AREA_0()</code>, danh sách liên kết hoặc mảng ưu tiên sẽ bị hỏng con trỏ (Race Condition).</li>\n        <li>Mảng Dynamic CAN ID (<code>CanIf_SetDynamicTxId</code>) và biến đếm Wakeup cũng dùng vùng găng bảo vệ tương tự.</li>\n      </ul>\n    </div>\n  </div>\n</div>"
      },
      {
        "title": "1.4 Các Phiên Bản Cấu Hình Pre-Compile / Link / Post-Build",
        "html": "\n<div class=\"hb-card\">\n  <h3>1.4 Phân Bố File Cấu Hình AUTOSAR CanIf</h3>\n  <table class=\"tbl\">\n    <tr><th>File Sinh Tự Động</th><th>Config Class</th><th>Thành Phần Lưu Trữ Chính</th></tr>\n    <tr><td class=\"mono\">CanIf_Cfg.h</td><td>Pre-Compile (VariantPC)</td><td>Các macro bật/tắt tính năng biên dịch: <code>CANIF_DEV_ERROR_DETECT</code>, <code>CANIF_PUBLIC_TX_BUFFERING</code>, <code>CANIF_PRIVATE_DLC_CHECK</code>, số lượng Tx/Rx PDU.</td></tr>\n    <tr><td class=\"mono\">CanIf_Lcfg.c</td><td>Link-Time</td><td>Bảng con trỏ hàm callback lên các Upper Layer khác nhau (<code>PduR_CanIfRxIndication</code>, <code>CanTp_RxIndication</code>, <code>CanNm_RxIndication</code>...).</td></tr>\n    <tr><td class=\"mono\">CanIf_PBcfg.c</td><td>Post-Build (VariantPB)</td><td>Bảng ánh xạ <code>CanId</code> ↔ <code>TxPduId/RxPduId</code> ↔ <code>HTH/HRH</code>, mặt nạ <code>CanIfRxPduCanIdMask</code>, dung lượng <code>CanIfTxBuffer</code> cho phép đổi bộ calibration mà không biên dịch lại mã nguồn.</td></tr>\n  </table>\n</div>"
      }
    ]
  },
  {
    "title": "2. HOH, CanIfTxBuffer & TriggerTx",
    "subs": [
      {
        "title": "2.1 FullCAN vs BasicCAN HOH",
        "html": "\n<div class=\"hb-card\">\n  <h3>2.1 Chiến Lược Phân Bổ Hardware Object Handle (HTH &amp; HRH)</h3>\n  <p>Trong phần cứng bộ điều khiển CAN (như M_CAN / FlexCAN), số lượng Hardware Message Buffer (Mailbox) có hạn (thường 32 hoặc 64 slot). AUTOSAR chia HOH thành hai loại để tối ưu giữa tốc độ CPU và dung lượng phần cứng:</p>\n  <svg class=\"hb-svg\" viewBox=\"0 0 820 256\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"hbArr\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"currentColor\" /></marker></defs><rect x=\"20\" y=\"16\" width=\"375\" height=\"224\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--ok)\" stroke-width=\"1.6\" /><text x=\"207.5\" y=\"108.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\"></text><text x=\"207.5\" y=\"124.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\"></text><text x=\"207.5\" y=\"140.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\"></text><text x=\"207.5\" y=\"156.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\"></text><rect x=\"36\" y=\"26\" width=\"343\" height=\"24\" rx=\"10\" fill=\"var(--ok-bg)\" stroke=\"var(--ok)\" stroke-width=\"1.2\" /><text x=\"207.5\" y=\"41.5\" text-anchor=\"middle\" fill=\"var(--ok)\" font-size=\"10\" font-weight=\"700\">FullCAN HOH (1 HOH : 1 L-PDU chuyên biệt)</text><rect x=\"42\" y=\"62\" width=\"140\" height=\"46\" rx=\"8\" fill=\"var(--panel-3)\" stroke=\"var(--pri)\" stroke-width=\"1.6\" /><text x=\"112.0\" y=\"81.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">TxPdu_0 (0x500)</text><text x=\"112.0\" y=\"97.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">CanNm Priority</text><rect x=\"235\" y=\"62\" width=\"140\" height=\"46\" rx=\"8\" fill=\"var(--panel-3)\" stroke=\"var(--ok)\" stroke-width=\"1.6\" /><text x=\"305.0\" y=\"81.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">HW Mailbox HTH_0</text><text x=\"305.0\" y=\"97.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Khớp 100% 1:1</text><line x1=\"182\" y1=\"85\" x2=\"235\" y2=\"85\" stroke=\"var(--ok)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--ok)\" /><text x=\"208.0\" y=\"76.0\" text-anchor=\"middle\" fill=\"var(--ok)\" font-size=\"9.5\" font-weight=\"700\">Direct</text><rect x=\"42\" y=\"124\" width=\"140\" height=\"46\" rx=\"8\" fill=\"var(--panel-3)\" stroke=\"var(--ok)\" stroke-width=\"1.6\" /><text x=\"112.0\" y=\"143.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">HW Mailbox HRH_0</text><text x=\"112.0\" y=\"159.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Lọc phần cứng</text><rect x=\"235\" y=\"124\" width=\"140\" height=\"46\" rx=\"8\" fill=\"var(--panel-3)\" stroke=\"var(--cyan)\" stroke-width=\"1.6\" /><text x=\"305.0\" y=\"143.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">RxPdu_2 (CanNm)</text><text x=\"305.0\" y=\"159.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Zero SwFilter CPU</text><line x1=\"182\" y1=\"147\" x2=\"235\" y2=\"147\" stroke=\"var(--ok)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--ok)\" /><text x=\"208.0\" y=\"138.0\" text-anchor=\"middle\" fill=\"var(--ok)\" font-size=\"9.5\" font-weight=\"700\">Fast</text><rect x=\"42\" y=\"190\" width=\"333\" height=\"34\" rx=\"10\" fill=\"var(--panel-3)\" stroke=\"var(--ok)\" stroke-width=\"1.2\" /><text x=\"208.5\" y=\"210.5\" text-anchor=\"middle\" fill=\"var(--ok)\" font-size=\"10\" font-weight=\"700\">Không cần CanIfTxBuffer, không tốn CPU lọc phần mềm</text><rect x=\"425\" y=\"16\" width=\"375\" height=\"224\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--warn)\" stroke-width=\"1.6\" /><text x=\"612.5\" y=\"108.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\"></text><text x=\"612.5\" y=\"124.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\"></text><text x=\"612.5\" y=\"140.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\"></text><text x=\"612.5\" y=\"156.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\"></text><rect x=\"441\" y=\"26\" width=\"343\" height=\"24\" rx=\"10\" fill=\"var(--warn-bg)\" stroke=\"var(--warn)\" stroke-width=\"1.2\" /><text x=\"612.5\" y=\"41.5\" text-anchor=\"middle\" fill=\"var(--warn)\" font-size=\"10\" font-weight=\"700\">BasicCAN HOH (N L-PDU dùng chung 1 HOH M:1)</text><rect x=\"442\" y=\"62\" width=\"145\" height=\"58\" rx=\"8\" fill=\"var(--panel-3)\" stroke=\"var(--pri)\" stroke-width=\"1.6\" /><text x=\"514.5\" y=\"79.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">TxPdu_1 (0x100)</text><text x=\"514.5\" y=\"95.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">TxPdu_2 (0x120)</text><text x=\"514.5\" y=\"111.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">TxPdu_3 (0x7E8)</text><rect x=\"638\" y=\"62\" width=\"145\" height=\"58\" rx=\"8\" fill=\"var(--panel-3)\" stroke=\"var(--warn)\" stroke-width=\"1.6\" /><text x=\"710.5\" y=\"79.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">HTH_1 + TxBuffer</text><text x=\"710.5\" y=\"95.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Sorted by CAN ID</text><text x=\"710.5\" y=\"111.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">SWS_CanIf_00381</text><line x1=\"587\" y1=\"91\" x2=\"638\" y2=\"91\" stroke=\"var(--warn)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--warn)\" /><text x=\"612.0\" y=\"82.0\" text-anchor=\"middle\" fill=\"var(--warn)\" font-size=\"9.5\" font-weight=\"700\">Queue</text><rect x=\"442\" y=\"132\" width=\"145\" height=\"52\" rx=\"8\" fill=\"var(--panel-3)\" stroke=\"var(--cyan)\" stroke-width=\"1.6\" /><text x=\"514.5\" y=\"154.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">HRH_1 BasicCAN</text><text x=\"514.5\" y=\"170.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Đón tất cả dải ID</text><rect x=\"638\" y=\"132\" width=\"145\" height=\"52\" rx=\"8\" fill=\"var(--panel-3)\" stroke=\"var(--pur)\" stroke-width=\"1.6\" /><text x=\"710.5\" y=\"154.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">Software Filter</text><text x=\"710.5\" y=\"170.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">MASK / BINARY_S</text><line x1=\"587\" y1=\"158\" x2=\"638\" y2=\"158\" stroke=\"var(--pur)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--pur)\" /><text x=\"612.0\" y=\"149.0\" text-anchor=\"middle\" fill=\"var(--pur)\" font-size=\"9.5\" font-weight=\"700\">Filter</text><rect x=\"442\" y=\"196\" width=\"341\" height=\"30\" rx=\"10\" fill=\"var(--panel-3)\" stroke=\"var(--warn)\" stroke-width=\"1.2\" /><text x=\"612.5\" y=\"214.5\" text-anchor=\"middle\" fill=\"var(--warn)\" font-size=\"10\" font-weight=\"700\">Tiết kiệm Mailbox phần cứng &amp; chống Priority Inversion</text></svg>\n  <table class=\"tbl\">\n    <tr><th>Tiêu Chí</th><th>FullCAN HOH (1:1)</th><th>BasicCAN HOH (M:1)</th></tr>\n    <tr><td><b>Tỷ lệ ánh xạ</b></td><td>1 HOH chỉ phục vụ duy nhất 1 L-PDU.</td><td>1 HOH dùng chung cho nhiều L-PDU khác nhau.</td></tr>\n    <tr><td><b>Chiều Nhận (HRH)</b></td><td>Bộ lọc phần cứng chấp nhận chính xác CAN ID → CanIf KHÔNG cần chạy Software Filter.</td><td>Phần cứng mở mặt nạ rộng → CanIf BẮT BUỘC chạy Software Acceptance Filter.</td></tr>\n    <tr><td><b>Chiều Truyền (HTH)</b></td><td>Không cần <code>CanIfTxBuffer</code>. Dùng cho tin tối khẩn cấp (CanNm / Airbag).</td><td>Phải bật <code>CanIfTxBuffer</code> để xếp hàng chống rớt tin khi Mailbox bận.</td></tr>\n  </table>\n</div>"
      },
      {
        "title": "2.2 CanIfTxBuffer & Priority Inversion",
        "html": "\n<div class=\"hb-card\">\n  <h3>2.2 Hàng Đợi Ưu Tiên CanIfTxBuffer &amp; Chống Đảo Ngược Ưu Tiên</h3>\n  <p>Nếu ECU truyền 2 bản tin khác nhau (<code>0x7E8</code> ưu tiên thấp và <code>0x100</code> ưu tiên cao) qua cùng một <code>BasicCAN HTH_1</code> theo kiểu FIFO đơn thuần, <code>0x7E8</code> gửi trước sẽ chặn đường <code>0x100</code> — hiện tượng này gọi là <b>Inner Priority Inversion</b>.</p>\n  <svg class=\"hb-svg\" viewBox=\"0 0 820 166\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"hbArr\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"currentColor\" /></marker></defs><rect x=\"20\" y=\"30\" width=\"170\" height=\"56\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--pri)\" stroke-width=\"1.6\" /><text x=\"105.0\" y=\"54.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">CanIf_Transmit()</text><text x=\"105.0\" y=\"70.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">0x7E8 trước, 0x100 sau</text><rect x=\"235\" y=\"30\" width=\"175\" height=\"56\" rx=\"8\" fill=\"var(--warn-bg)\" stroke=\"var(--warn)\" stroke-width=\"1.6\" /><text x=\"322.5\" y=\"54.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">Can_Write(HTH_1)</text><text x=\"322.5\" y=\"70.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Trả về CAN_BUSY</text><rect x=\"455\" y=\"22\" width=\"180\" height=\"72\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--cyan)\" stroke-width=\"1.6\" /><text x=\"545.0\" y=\"46.0\" text-anchor=\"middle\" fill=\"var(--cyan)\" font-size=\"12\" font-weight=\"800\">CanIfTxBuffer (RAM)</text><text x=\"545.0\" y=\"62.0\" text-anchor=\"middle\" fill=\"var(--ok)\" font-size=\"10\" font-weight=\"500\">#1: 0x100 (Cao nhất)</text><text x=\"545.0\" y=\"78.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">#2: 0x7E8 (Thấp hơn)</text><rect x=\"675\" y=\"30\" width=\"125\" height=\"56\" rx=\"8\" fill=\"var(--ok-bg)\" stroke=\"var(--ok)\" stroke-width=\"1.6\" /><text x=\"737.5\" y=\"54.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">TxConfirm() ISR</text><text x=\"737.5\" y=\"70.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Tự động xả #1!</text><line x1=\"190\" y1=\"58\" x2=\"235\" y2=\"58\" stroke=\"var(--pri)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--pri)\" /><text x=\"212.0\" y=\"48.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"9.5\" font-weight=\"700\">Write</text><line x1=\"410\" y1=\"58\" x2=\"455\" y2=\"58\" stroke=\"var(--warn)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--warn)\" /><text x=\"432.0\" y=\"48.0\" text-anchor=\"middle\" fill=\"var(--warn)\" font-size=\"9.5\" font-weight=\"700\">BUSY</text><line x1=\"635\" y1=\"58\" x2=\"675\" y2=\"58\" stroke=\"var(--ok)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--ok)\" /><text x=\"655.0\" y=\"48.0\" text-anchor=\"middle\" fill=\"var(--ok)\" font-size=\"9.5\" font-weight=\"700\">Dequeue</text><rect x=\"20\" y=\"114\" width=\"780\" height=\"34\" rx=\"10\" fill=\"var(--pur-bg)\" stroke=\"var(--pur)\" stroke-width=\"1.2\" /><text x=\"410.0\" y=\"134.5\" text-anchor=\"middle\" fill=\"var(--pur)\" font-size=\"10\" font-weight=\"700\">SchM_Enter_CanIf_EXCLUSIVE_AREA_0() bảo vệ hàng đợi khỏi Race Condition giữa Task &amp; ISR; trùng TxPduId sẽ ghi đè dữ liệu mới (SWS_CanIf_00068)</text></svg>\n  <ul>\n    <li><b>Sắp xếp theo CAN ID:</b> Khi <code>Can_Write()</code> trả về <code>CAN_BUSY</code>, CanIf chèn L-PDU vào <code>CanIfTxBuffer</code> theo thứ tự <b>CAN ID tăng dần</b> (ID nhỏ nhất = ưu tiên bus cao nhất đứng đầu hàng đợi).</li>\n    <li><b>Ghi đè cùng TxPduId (SWS_CanIf_00068):</b> Nếu cùng một <code>TxPduId</code> được gọi <code>Transmit()</code> lần 2 khi bản cũ vẫn nằm trong <code>CanIfTxBuffer</code>, bản mới sẽ ghi đè dữ liệu vào chính slot đó thay vì chiếm 2 slot.</li>\n    <li><b>Tự động xả trong TxConfirmation():</b> Ngay khi ngắt phần cứng <code>CanIf_TxConfirmation()</code> báo HTH vừa rảnh, CanIf nhấc ngay phần tử đầu hàng đợi (ID nhỏ nhất) gọi <code>Can_Write()</code> trước khi thoát ngắt!</li>\n  </ul>\n</div>"
      },
      {
        "title": "2.3 TriggerTransmit & DynamicTxId",
        "html": "\n<div class=\"hb-card\">\n  <h3>2.3 Kéo Dữ Liệu Tức Thời (TriggerTransmit) &amp; Đổi ID Động (SetDynamicTxId)</h3>\n  <svg class=\"hb-svg\" viewBox=\"0 0 820 198\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"hbArr\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"currentColor\" /></marker></defs><rect x=\"20\" y=\"20\" width=\"780\" height=\"72\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--cyan)\" stroke-width=\"1.6\" /><text x=\"410.0\" y=\"52.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\"></text><text x=\"410.0\" y=\"68.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\"></text><rect x=\"32\" y=\"28\" width=\"185\" height=\"22\" rx=\"10\" fill=\"var(--cyan-bg)\" stroke=\"var(--cyan)\" stroke-width=\"1.2\" /><text x=\"124.5\" y=\"42.5\" text-anchor=\"middle\" fill=\"var(--cyan)\" font-size=\"10\" font-weight=\"700\">CanIf_TriggerTransmit()</text><rect x=\"232\" y=\"28\" width=\"165\" height=\"52\" rx=\"8\" fill=\"var(--panel-3)\" stroke=\"var(--ok)\" stroke-width=\"1.6\" /><text x=\"314.5\" y=\"50.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">CanDrv Ready Tx</text><text x=\"314.5\" y=\"66.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Sát giờ lên bus</text><rect x=\"435\" y=\"28\" width=\"175\" height=\"52\" rx=\"8\" fill=\"var(--panel-3)\" stroke=\"var(--cyan)\" stroke-width=\"1.6\" /><text x=\"522.5\" y=\"50.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">CanIf_TriggerTransmit</text><text x=\"522.5\" y=\"66.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Kéo dữ liệu tươi</text><rect x=\"645\" y=\"28\" width=\"140\" height=\"52\" rx=\"8\" fill=\"var(--panel-3)\" stroke=\"var(--pri)\" stroke-width=\"1.6\" /><text x=\"715.0\" y=\"50.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">PduR_CanIfTrigTx()</text><text x=\"715.0\" y=\"66.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Nạp Rolling Cnt</text><line x1=\"397\" y1=\"54\" x2=\"435\" y2=\"54\" stroke=\"var(--ok)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--ok)\" /><line x1=\"610\" y1=\"54\" x2=\"645\" y2=\"54\" stroke=\"var(--cyan)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--cyan)\" /><rect x=\"20\" y=\"110\" width=\"780\" height=\"72\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--pur)\" stroke-width=\"1.6\" /><text x=\"410.0\" y=\"142.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\"></text><text x=\"410.0\" y=\"158.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\"></text><rect x=\"32\" y=\"118\" width=\"185\" height=\"22\" rx=\"10\" fill=\"var(--pur-bg)\" stroke=\"var(--pur)\" stroke-width=\"1.2\" /><text x=\"124.5\" y=\"132.5\" text-anchor=\"middle\" fill=\"var(--pur)\" font-size=\"10\" font-weight=\"700\">CanIf_SetDynamicTxId()</text><rect x=\"232\" y=\"118\" width=\"165\" height=\"52\" rx=\"8\" fill=\"var(--panel-3)\" stroke=\"var(--pri)\" stroke-width=\"1.6\" /><text x=\"314.5\" y=\"140.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">J1939Nm / DoCAN</text><text x=\"314.5\" y=\"156.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Đổi Node Addr RAM</text><rect x=\"435\" y=\"118\" width=\"175\" height=\"52\" rx=\"8\" fill=\"var(--panel-3)\" stroke=\"var(--pur)\" stroke-width=\"1.6\" /><text x=\"522.5\" y=\"140.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">CanIf_DynTxId[Pdu]</text><text x=\"522.5\" y=\"156.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Ghi đè Can_IdType</text><rect x=\"645\" y=\"118\" width=\"140\" height=\"52\" rx=\"8\" fill=\"var(--panel-3)\" stroke=\"var(--ok)\" stroke-width=\"1.6\" /><text x=\"715.0\" y=\"140.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">CanIf_Transmit()</text><text x=\"715.0\" y=\"156.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Mang CAN ID mới</text><line x1=\"397\" y1=\"144\" x2=\"435\" y2=\"144\" stroke=\"var(--pri)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--pri)\" /><line x1=\"610\" y1=\"144\" x2=\"645\" y2=\"144\" stroke=\"var(--pur)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--pur)\" /></svg>\n  <div class=\"hb-grid2\">\n    <div>\n      <h4>CanIf_TriggerTransmit() (SWS_CanIf_00883)</h4>\n      <p>Khi một TxPdu phải xếp hàng lâu hoặc đồng bộ chặt với chu kỳ bus (ví dụ mang <i>E2E Rolling Counter / CRC</i>), dữ liệu truyền ở bước <code>Transmit()</code> có thể bị cũ. Bật <code>CanIfTriggerTransmitSupport</code> cho phép <code>CanDrv</code> gọi callback kéo dữ liệu tươi mới từ <code>PduR/Com</code> vào đúng micro-giây cuối cùng trước khi phát.</p>\n    </div>\n    <div>\n      <h4>CanIf_SetDynamicTxId() (SWS_CanIf_00189)</h4>\n      <p>Rất phổ biến trong mạng xe tải <b>SAE J1939</b> (<code>J1939Nm</code> Address Claiming thay đổi Source Address 8-bit cuối của CAN ID 29-bit) hoặc chẩn đoán động <b>DoCAN</b>. CanIf giữ một mảng RAM lưu CAN ID hiện hành thay vì bảng hằng số Flash ROM.</p>\n    </div>\n  </div>\n</div>"
      },
      {
        "title": "2.4 Vòng Đời TxConfirmation & Notification State",
        "html": "\n<div class=\"hb-card\">\n  <h3>2.4 CanIf_GetTxConfirmationState() &amp; Kiểm Soát Bus Hoạt Động</h3>\n  <p>Trong bài toán đồng bộ tắt máy hoặc xác nhận kết nối bus (được <code>CanSM</code> hoặc <code>BswM</code> hỏi định kỳ), hàm <code>CanIf_GetTxConfirmationState(ControllerId)</code> trả về một trong hai giá trị:</p>\n  <ul>\n    <li><code>CANIF_NO_NOTIFICATION (0)</code>: Kể từ lần chuyển sang <code>CAN_CS_STARTED</code> hoặc sau lần <code>Bus-Off</code> / <code>STOPPED</code> gần nhất, chưa có khung Tx nào được xác nhận ACK thành công trên bus.</li>\n    <li><code>CANIF_TX_RX_NOTIFICATION (1)</code>: Đã truyền thành công ít nhất 1 khung kể từ lần reset state gần nhất. Trạng thái này tự động xóa về 0 khi Controller rời khỏi <code>CAN_CS_STARTED</code> (<code>SWS_CanIf_00734</code>).</li>\n  </ul>\n</div>"
      }
    ]
  },
  {
    "title": "3. Rx Filter, DLC Check & CAN-FD",
    "subs": [
      {
        "title": "3.1 Software Acceptance Filter",
        "html": "\n<div class=\"hb-card\">\n  <h3>3.1 Thuật Toán Lọc Phần Mềm Cho BasicCAN HRH (CanIfPrivateSoftwareFilterType)</h3>\n  <p>Khi <code>BasicCAN HRH</code> thu thập mọi khung tin lọt qua mặt nạ phần cứng, <code>CanIf_RxIndication()</code> phải nhanh chóng phân loại xem khung đó thuộc về <code>RxPduId</code> nào hoặc loại bỏ ngay để tiết kiệm tải CPU:</p>\n  <svg class=\"hb-svg\" viewBox=\"0 0 820 190\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"hbArr\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"currentColor\" /></marker></defs><rect x=\"16\" y=\"36\" width=\"130\" height=\"62\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--ok)\" stroke-width=\"1.6\" /><text x=\"81.0\" y=\"63.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">CanDrv Rx ISR</text><text x=\"81.0\" y=\"79.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Mailbox + PduInfo</text><rect x=\"172\" y=\"36\" width=\"136\" height=\"62\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--warn)\" stroke-width=\"1.6\" /><text x=\"240.0\" y=\"63.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">PduMode Gate</text><text x=\"240.0\" y=\"79.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">!= CANIF_OFFLINE</text><rect x=\"336\" y=\"36\" width=\"152\" height=\"62\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--pur)\" stroke-width=\"1.6\" /><text x=\"412.0\" y=\"63.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">Software Filter</text><text x=\"412.0\" y=\"79.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">MASK / BINARY_S</text><rect x=\"516\" y=\"36\" width=\"136\" height=\"62\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--cyan)\" stroke-width=\"1.6\" /><text x=\"584.0\" y=\"63.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">DLC Check (0x32)</text><text x=\"584.0\" y=\"79.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Act &gt;= MinDlc</text><rect x=\"678\" y=\"36\" width=\"126\" height=\"62\" rx=\"8\" fill=\"var(--pri-bg)\" stroke=\"var(--pri)\" stroke-width=\"1.6\" /><text x=\"741.0\" y=\"63.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">&lt;User&gt;_RxInd()</text><text x=\"741.0\" y=\"79.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">PduR / Tp / Nm</text><rect x=\"336\" y=\"128\" width=\"152\" height=\"46\" rx=\"8\" fill=\"var(--panel-3)\" stroke=\"var(--mut)\" stroke-width=\"1.6\" /><text x=\"412.0\" y=\"147.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">Drop Lặng Lẽ</text><text x=\"412.0\" y=\"163.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Không khớp CAN ID</text><rect x=\"516\" y=\"128\" width=\"288\" height=\"46\" rx=\"8\" fill=\"var(--err-bg)\" stroke=\"var(--err)\" stroke-width=\"1.6\" /><text x=\"660.0\" y=\"147.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">Det_ReportRuntimeError(60, 0x32)</text><text x=\"660.0\" y=\"163.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">CANIF_E_INVALID_DATA_LENGTH + IdsM</text><line x1=\"146\" y1=\"67\" x2=\"172\" y2=\"67\" stroke=\"var(--ok)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--ok)\" /><line x1=\"308\" y1=\"67\" x2=\"336\" y2=\"67\" stroke=\"var(--warn)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--warn)\" /><line x1=\"488\" y1=\"67\" x2=\"516\" y2=\"67\" stroke=\"var(--pur)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--pur)\" /><line x1=\"652\" y1=\"67\" x2=\"678\" y2=\"67\" stroke=\"var(--cyan)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--cyan)\" /><line x1=\"412\" y1=\"98\" x2=\"412\" y2=\"128\" stroke=\"var(--mut)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--mut)\" /><text x=\"435.0\" y=\"116.0\" text-anchor=\"middle\" fill=\"var(--mut)\" font-size=\"9.5\" font-weight=\"700\">Miss</text><line x1=\"584\" y1=\"98\" x2=\"584\" y2=\"128\" stroke=\"var(--err)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--err)\" /><text x=\"608.0\" y=\"116.0\" text-anchor=\"middle\" fill=\"var(--err)\" font-size=\"9.5\" font-weight=\"700\">Short</text></svg>\n  <table class=\"tbl\">\n    <tr><th>Thuật Toán</th><th>Độ Phức Tạp</th><th>Ứng Dụng Thực Tế</th></tr>\n    <tr><td class=\"mono\">BINARY_SEARCH</td><td>O(log N)</td><td>Khuyên dùng khi số RxPdu nhiều (20..200 ID); bảng cấu hình phải sắp theo thứ tự CAN ID.</td></tr>\n    <tr><td class=\"mono\">MASK</td><td>O(N) với Bitmask</td><td>Phép toán <code>(RxCanId &amp; Mask) == (CfgCanId &amp; Mask)</code> — cực mạnh cho dải ID <code>CanNm 0x500..0x5FF</code> (Mask <code>0x700</code>) hoặc J1939 PGN.</td></tr>\n    <tr><td class=\"mono\">INDEX / TABLE</td><td>O(1)</td><td>Tra mảng trực tiếp tốn RAM/Flash nhưng độ trễ thấp nhất.</td></tr>\n    <tr><td class=\"mono\">LINEAR</td><td>O(N)</td><td>Chỉ phù hợp ECU nhỏ dưới ~10 RxPdu trên BasicCAN.</td></tr>\n  </table>\n</div>"
      },
      {
        "title": "3.2 DLC Check & Lỗi Runtime 0x32",
        "html": "\n<div class=\"hb-card\">\n  <h3>3.2 Bảo Vệ Bộ Nhớ Với CanIfPrivateDlcCheck &amp; Runtime Error 0x32</h3>\n  <p>Một trong những lỗi phổ biến và nguy hiểm nhất trên bus CAN là nhận được khung có <b>DLC thực tế ngắn hơn kỳ vọng</b> (do nhiễu hoặc giả mạo / ECU đối tác cấu hình sai). Nếu chuyển thẳng lên tầng <code>Com</code> hoặc <code>SecOC</code>, tác vụ giải mã sẽ đọc vượt ra ngoài buffer hợp lệ (<b>Out-of-Bounds Memory Read</b>).</p>\n  <ul>\n    <li><b>Điều kiện đạt:</b> <code>PduInfoPtr-&gt;SduLength &gt;= CanIfRxPduDataLength</code> (SWS_CanIf_00026). Lưu ý cho phép khung nhận DÀI HƠN hoặc bằng độ dài cấu hình, nhưng TUYỆT ĐỐI không chấp nhận NGẮN HƠN!</li>\n    <li><b>Khi vi phạm:</b> CanIf dừng ngay chuỗi xử lý, báo Runtime Error <code>CANIF_E_INVALID_DATA_LENGTH (0x32)</code> (và bắn sự kiện an ninh sang <code>IdsM</code> nếu bật), không gọi callback tầng trên.</li>\n  </ul>\n</div>"
      },
      {
        "title": "3.3 CAN FD 64B, Bit Rate Switch & Truncation",
        "html": "\n<div class=\"hb-card\">\n  <h3>3.3 Tối Ưu CAN FD (64 Bytes + BRS) &amp; Cơ Chế Cắt Ngắn CanIfTxPduTruncation</h3>\n  <div class=\"hb-grid2\">\n    <div>\n      <h4>Đặc điểm CAN FD trong CanIf</h4>\n      <ul>\n        <li>Bit 30 của <code>Can_IdType</code> báo cho <code>CanDrv</code> biết chuyển sang định dạng khung FD (Payload tới 64 Bytes) và kích hoạt Bit Rate Switch (BRS — ví dụ Arbitration 500 kbps, Data phase 2 Mbps hoặc 5 Mbps).</li>\n        <li>Trên bus CAN FD, các giá trị DLC từ 9..15 được ánh xạ phi tuyến thành <code>12, 16, 20, 24, 32, 48, 64</code> bytes.</li>\n      </ul>\n    </div>\n    <div>\n      <h4>Xử lý quá khổ: CANIF_E_TXPDU_LENGTH_EXCEEDED (0x33)</h4>\n      <p>Nếu tầng trên gọi <code>CanIf_Transmit()</code> với độ dài SduLength lớn hơn <code>maxLen</code> (8B với CAN 2.0 hoặc 64B với FD):</p>\n      <ul>\n        <li>Luôn báo Runtime Error <code>0x33</code>.</li>\n        <li>Nếu <code>CanIfTxPduTruncation = TRUE</code>: Tự động cắt bớt về <code>maxLen</code> và phát tiếp.</li>\n        <li>Nếu <code>CanIfTxPduTruncation = FALSE</code>: Hủy bản tin và trả về <code>E_NOT_OK</code>!</li>\n      </ul>\n    </div>\n  </div>\n</div>"
      },
      {
        "title": "3.4 Dispatch Đa Tầng Trên & Polling ReadRxPduData",
        "html": "\n<div class=\"hb-card\">\n  <h3>3.4 Định Tuyến Callback Đa Tầng Trên vs Chế Độ Đọc Polling</h3>\n  <p>Tùy từng <code>RxPduId</code>, mảng <code>CanIf_RxPduConfig[]</code> lưu con trỏ hàm đích tương ứng trong Link-Time/Post-Build:</p>\n  <table class=\"tbl\">\n    <tr><th>Upper Layer</th><th>Callback Nhận</th><th>Callback Xác Nhận Phát</th></tr>\n    <tr><td><b>PduR (COM / SecOC)</b></td><td class=\"mono\">PduR_CanIfRxIndication()</td><td class=\"mono\">PduR_CanIfTxConfirmation()</td></tr>\n    <tr><td><b>CanTp (UDS ISO 15765-2)</b></td><td class=\"mono\">CanTp_RxIndication()</td><td class=\"mono\">CanTp_TxConfirmation()</td></tr>\n    <tr><td><b>CanNm (Network Mgmt)</b></td><td class=\"mono\">CanNm_RxIndication()</td><td class=\"mono\">CanNm_TxConfirmation()</td></tr>\n    <tr><td><b>CanTSyn (TimeSync)</b></td><td class=\"mono\">CanTSyn_RxIndication()</td><td class=\"mono\">CanTSyn_TxConfirmation()</td></tr>\n  </table>\n  <p style=\"margin-top:6px\"><b>Polling Mode (<code>CanIfRxPduReadDataAndNotif</code>):</b> Dành cho một số Complex Device Driver (CDD) đọc theo chu kỳ thay vì ngắt: CanIf chép dữ liệu vào RAM nội bộ để CDD gọi <code>CanIf_ReadRxPduData()</code> &amp; <code>CanIf_ReadRxNotifStatus()</code>.</p>\n</div>"
      }
    ]
  },
  {
    "title": "4. Controller/PduMode, PN & Bus-Off",
    "subs": [
      {
        "title": "4.1 Máy Trạng Thái ControllerMode (SWS_CanIf_00308)",
        "html": "\n<div class=\"hb-card\">\n  <h3>4.1 Điều Phối Can_ControllerStateType Giữa CanSM và CanDrv</h3>\n  <p>CanIf giữ bản sao trạng thái Controller tại RAM và chỉ huy MCAL <code>Can_SetControllerMode()</code> tuân thủ nghiêm ngặt đồ thị chuyển trạng thái dưới đây:</p>\n  <svg class=\"hb-svg\" viewBox=\"0 0 820 250\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"hbArr\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"currentColor\" /></marker></defs><rect x=\"30\" y=\"56\" width=\"150\" height=\"62\" rx=\"8\" fill=\"var(--panel-3)\" stroke=\"var(--bdr)\" stroke-width=\"1.6\" /><text x=\"105.0\" y=\"83.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">CAN_CS_UNINIT</text><text x=\"105.0\" y=\"99.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Chưa CanIf_Init()</text><rect x=\"240\" y=\"56\" width=\"170\" height=\"62\" rx=\"8\" fill=\"var(--warn-bg)\" stroke=\"var(--warn)\" stroke-width=\"1.6\" /><text x=\"325.0\" y=\"83.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">CAN_CS_STOPPED</text><text x=\"325.0\" y=\"99.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Xóa TxBuffer, Chờ</text><rect x=\"495\" y=\"56\" width=\"185\" height=\"62\" rx=\"8\" fill=\"var(--ok-bg)\" stroke=\"var(--ok)\" stroke-width=\"1.6\" /><text x=\"587.5\" y=\"83.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">CAN_CS_STARTED</text><text x=\"587.5\" y=\"99.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Tx &amp; Rx Hoạt Động</text><rect x=\"240\" y=\"172\" width=\"170\" height=\"62\" rx=\"8\" fill=\"var(--pur-bg)\" stroke=\"var(--pur)\" stroke-width=\"1.6\" /><text x=\"325.0\" y=\"199.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">CAN_CS_SLEEP</text><text x=\"325.0\" y=\"215.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">HW Sleep Chờ WUF</text><line x1=\"180\" y1=\"87\" x2=\"240\" y2=\"87\" stroke=\"var(--pri)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--pri)\" /><text x=\"210.0\" y=\"77.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"9.5\" font-weight=\"700\">Init</text><line x1=\"410\" y1=\"76\" x2=\"495\" y2=\"76\" stroke=\"var(--ok)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--ok)\" /><text x=\"452.0\" y=\"66.0\" text-anchor=\"middle\" fill=\"var(--ok)\" font-size=\"9.5\" font-weight=\"700\">STARTED</text><line x1=\"495\" y1=\"102\" x2=\"410\" y2=\"102\" stroke=\"var(--warn)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--warn)\" /><text x=\"452.0\" y=\"118.0\" text-anchor=\"middle\" fill=\"var(--warn)\" font-size=\"9.5\" font-weight=\"700\">STOP / BusOff</text><line x1=\"305\" y1=\"118\" x2=\"305\" y2=\"172\" stroke=\"var(--pur)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--pur)\" /><text x=\"278.0\" y=\"148.0\" text-anchor=\"middle\" fill=\"var(--pur)\" font-size=\"9.5\" font-weight=\"700\">SLEEP</text><line x1=\"345\" y1=\"172\" x2=\"345\" y2=\"118\" stroke=\"var(--warn)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--warn)\" /><text x=\"380.0\" y=\"148.0\" text-anchor=\"middle\" fill=\"var(--warn)\" font-size=\"9.5\" font-weight=\"700\">STOPPED</text><line x1=\"585\" y1=\"118\" x2=\"410\" y2=\"203\" stroke=\"var(--err)\" stroke-width=\"1.8\" stroke-dasharray=\"4 3\" marker-end=\"url(#hbArr)\" style=\"color:var(--err)\" /><text x=\"558.0\" y=\"190.0\" text-anchor=\"middle\" fill=\"var(--err)\" font-size=\"9.5\" font-weight=\"700\">CẤM đi thẳng STARTED -&gt; SLEEP!</text></svg>\n  <ul>\n    <li><b>Quy tắc vàng:</b> KHÔNG BAO GIỜ được chuyển trực tiếp từ <code>CAN_CS_STARTED</code> sang <code>CAN_CS_SLEEP</code>! Phải đi qua trạm trung chuyển <code>CAN_CS_STOPPED</code> để hủy sạch hàng đợi <code>CanIfTxBuffer</code> và đưa bộ điều khiển về trạng thái an toàn trước khi ngủ.</li>\n    <li>Mỗi lần hoàn tất chuyển đổi, <code>CanDrv</code> gọi ngược callback <code>CanIf_ControllerModeIndication()</code> để CanIf thông báo lên <code>CanSM</code>.</li>\n  </ul>\n</div>"
      },
      {
        "title": "4.2 Bốn Chế Độ PduMode & TX_OFFLINE_ACTIVE",
        "html": "\n<div class=\"hb-card\">\n  <h3>4.2 Giải Phẫu Cổng Logic CanIf_PduModeType &amp; ECU Passive Mode</h3>\n  <p>Trong khi <code>ControllerMode</code> tắt/bật toàn bộ khối phần cứng ngoại vi CAN, <code>CanIf_PduModeType</code> là cổng khóa logic ở tầng phần mềm cho phép CanSM linh hoạt khóa riêng từng chiều Tx hoặc Rx:</p>\n  <svg class=\"hb-svg\" viewBox=\"0 0 820 166\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"hbArr\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"currentColor\" /></marker></defs><rect x=\"20\" y=\"18\" width=\"180\" height=\"130\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--err)\" stroke-width=\"1.6\" /><text x=\"110.0\" y=\"63.0\" text-anchor=\"middle\" fill=\"var(--err)\" font-size=\"12\" font-weight=\"800\">CANIF_OFFLINE (0x00)</text><text x=\"110.0\" y=\"79.0\" text-anchor=\"middle\" fill=\"var(--err)\" font-size=\"10\" font-weight=\"500\">Tx Path: LOCKED</text><text x=\"110.0\" y=\"95.0\" text-anchor=\"middle\" fill=\"var(--err)\" font-size=\"10\" font-weight=\"500\">Rx Path: LOCKED</text><text x=\"110.0\" y=\"111.0\" text-anchor=\"middle\" fill=\"var(--mut)\" font-size=\"10\" font-weight=\"500\">Dùng khi Init / Stop</text><rect x=\"218\" y=\"18\" width=\"185\" height=\"130\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--warn)\" stroke-width=\"1.6\" /><text x=\"310.5\" y=\"63.0\" text-anchor=\"middle\" fill=\"var(--err)\" font-size=\"12\" font-weight=\"800\">CANIF_TX_OFFLINE (1)</text><text x=\"310.5\" y=\"79.0\" text-anchor=\"middle\" fill=\"var(--err)\" font-size=\"10\" font-weight=\"500\">Tx Path: LOCKED</text><text x=\"310.5\" y=\"95.0\" text-anchor=\"middle\" fill=\"var(--ok)\" font-size=\"10\" font-weight=\"500\">Rx Path: OPEN!</text><text x=\"310.5\" y=\"111.0\" text-anchor=\"middle\" fill=\"var(--mut)\" font-size=\"10\" font-weight=\"500\">SilentCom / Bus-Off</text><rect x=\"421\" y=\"18\" width=\"195\" height=\"130\" rx=\"8\" fill=\"var(--warn-bg)\" stroke=\"var(--warn)\" stroke-width=\"1.6\" /><text x=\"518.5\" y=\"63.0\" text-anchor=\"middle\" fill=\"var(--warn)\" font-size=\"12\" font-weight=\"800\">TX_OFFLINE_ACTIVE (2)</text><text x=\"518.5\" y=\"79.0\" text-anchor=\"middle\" fill=\"var(--warn)\" font-size=\"10\" font-weight=\"500\">Can_Write(): SKIP</text><text x=\"518.5\" y=\"95.0\" text-anchor=\"middle\" fill=\"var(--cyan)\" font-size=\"10\" font-weight=\"800\">TxConfirm(): VIRTUAL!</text><text x=\"518.5\" y=\"111.0\" text-anchor=\"middle\" fill=\"var(--mut)\" font-size=\"10\" font-weight=\"500\">Passive ECU Mode</text><rect x=\"634\" y=\"18\" width=\"166\" height=\"130\" rx=\"8\" fill=\"var(--ok-bg)\" stroke=\"var(--ok)\" stroke-width=\"1.6\" /><text x=\"717.0\" y=\"63.0\" text-anchor=\"middle\" fill=\"var(--ok)\" font-size=\"12\" font-weight=\"800\">CANIF_ONLINE (0x03)</text><text x=\"717.0\" y=\"79.0\" text-anchor=\"middle\" fill=\"var(--ok)\" font-size=\"10\" font-weight=\"500\">Tx Path: OPEN</text><text x=\"717.0\" y=\"95.0\" text-anchor=\"middle\" fill=\"var(--ok)\" font-size=\"10\" font-weight=\"500\">Rx Path: OPEN</text><text x=\"717.0\" y=\"111.0\" text-anchor=\"middle\" fill=\"var(--mut)\" font-size=\"10\" font-weight=\"500\">Full Communication</text></svg>\n  <p style=\"margin-top:6px\"><b>Điểm đắt giá nhất — <code>CANIF_TX_OFFLINE_ACTIVE (0x02)</code> (SWS_CanIf_00072):</b> Dùng khi ECU đang chạy chế độ <i>Passive / Listen-Only Validation</i> hoặc không muốn phát xung lên bus nhưng vẫn giữ tầng ứng dụng <code>Com/PduR</code> hoạt động bình thường. Khi nhận lệnh <code>CanIf_Transmit()</code>, CanIf <b>bỏ qua <code>Can_Write()</code></b> và <b>tự bắn ngay callback ảo <code>&lt;User&gt;_TxConfirmation(E_OK)</code></b> lên tầng trên!</p>\n</div>"
      },
      {
        "title": "4.3 Partial Networking (PN) Tx Filter",
        "html": "\n<div class=\"hb-card\">\n  <h3>4.3 Bộ Lọc Truyền Partial Networking &amp; TJA1145 Transceiver</h3>\n  <svg class=\"hb-svg\" viewBox=\"0 0 820 198\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"hbArr\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"currentColor\" /></marker></defs><rect x=\"20\" y=\"18\" width=\"375\" height=\"164\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--pur)\" stroke-width=\"1.6\" /><text x=\"207.5\" y=\"80.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\"></text><text x=\"207.5\" y=\"96.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\"></text><text x=\"207.5\" y=\"112.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\"></text><text x=\"207.5\" y=\"128.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\"></text><rect x=\"35\" y=\"28\" width=\"345\" height=\"24\" rx=\"10\" fill=\"var(--pur-bg)\" stroke=\"var(--pur)\" stroke-width=\"1.2\" /><text x=\"207.5\" y=\"43.5\" text-anchor=\"middle\" fill=\"var(--pur)\" font-size=\"10\" font-weight=\"700\">Partial Networking Tx Filter (SWS_CanIf_00750)</text><rect x=\"38\" y=\"64\" width=\"155\" height=\"50\" rx=\"8\" fill=\"var(--panel-3)\" stroke=\"var(--warn)\" stroke-width=\"1.6\" /><text x=\"115.5\" y=\"85.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">CanIfPnFilter=ON</text><text x=\"115.5\" y=\"101.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Chặn App TxPdu</text><rect x=\"222\" y=\"64\" width=\"155\" height=\"50\" rx=\"8\" fill=\"var(--panel-3)\" stroke=\"var(--ok)\" stroke-width=\"1.6\" /><text x=\"299.5\" y=\"85.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">TxPdu_0 (PN=TRUE)</text><text x=\"299.5\" y=\"101.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">CanNm đi xuyên!</text><line x1=\"193\" y1=\"89\" x2=\"222\" y2=\"89\" stroke=\"var(--pur)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--pur)\" /><rect x=\"38\" y=\"130\" width=\"339\" height=\"36\" rx=\"10\" fill=\"var(--ok-bg)\" stroke=\"var(--ok)\" stroke-width=\"1.2\" /><text x=\"207.5\" y=\"151.5\" text-anchor=\"middle\" fill=\"var(--ok)\" font-size=\"10\" font-weight=\"700\">ConfirmPnAvailability() -&gt; Mở khóa toàn bộ TxPdu!</text><rect x=\"425\" y=\"18\" width=\"375\" height=\"164\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--err)\" stroke-width=\"1.6\" /><text x=\"612.5\" y=\"80.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\"></text><text x=\"612.5\" y=\"96.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\"></text><text x=\"612.5\" y=\"112.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\"></text><text x=\"612.5\" y=\"128.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\"></text><rect x=\"440\" y=\"28\" width=\"345\" height=\"24\" rx=\"10\" fill=\"var(--err-bg)\" stroke=\"var(--err)\" stroke-width=\"1.2\" /><text x=\"612.5\" y=\"43.5\" text-anchor=\"middle\" fill=\"var(--err)\" font-size=\"10\" font-weight=\"700\">Phản Ứng Tức Thì Khi CanIf_ControllerBusOff()</text><rect x=\"442\" y=\"64\" width=\"160\" height=\"50\" rx=\"8\" fill=\"var(--panel-3)\" stroke=\"var(--err)\" stroke-width=\"1.6\" /><text x=\"522.0\" y=\"85.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">1) Ctrl = STOPPED</text><text x=\"522.0\" y=\"101.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">2) Pdu = TX_OFFLINE</text><rect x=\"624\" y=\"64\" width=\"160\" height=\"50\" rx=\"8\" fill=\"var(--panel-3)\" stroke=\"var(--warn)\" stroke-width=\"1.6\" /><text x=\"704.0\" y=\"85.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">3) Clear TxBuffer</text><text x=\"704.0\" y=\"101.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">4) TxConf = NO_NOTIF</text><line x1=\"602\" y1=\"89\" x2=\"624\" y2=\"89\" stroke=\"var(--err)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--err)\" /><rect x=\"442\" y=\"130\" width=\"342\" height=\"36\" rx=\"10\" fill=\"var(--err-bg)\" stroke=\"var(--err)\" stroke-width=\"1.2\" /><text x=\"613.0\" y=\"151.5\" text-anchor=\"middle\" fill=\"var(--err)\" font-size=\"10\" font-weight=\"700\">Gọi CanSM_ControllerBusOff() kích hoạt BOR L1/L2</text></svg>\n  <p>Với công nghệ Partial Networking, một ECU được đánh thức cục bộ không được phép làm ồn bus bằng bản tin ứng dụng cho đến khi cụm mạng PN xác nhận sẵn sàng:</p>\n  <ul>\n    <li>Khi <code>CanIfPnFilterEnabled = TRUE</code>, mọi lời gọi <code>CanIf_Transmit()</code> đều bị chặn với mã <code>E_NOT_OK</code> ngoại trừ các L-PDU đánh dấu <code>CanIfTxPduPnFilterPdu = TRUE</code> (thường là <code>CanNm</code> PDU).</li>\n    <li>Sau khi hoàn tất bắt tay NM hoặc <code>CanTrcv</code> xác nhận cờ WUF hợp lệ, hàm <code>CanIf_ConfirmPnAvailability()</code> được gọi để gỡ bỏ bộ lọc PN trên Controller đó.</li>\n  </ul>\n</div>"
      },
      {
        "title": "4.4 Phản Ứng Khi Bus-Off (SWS_CanIf_00218)",
        "html": "\n<div class=\"hb-card\">\n  <h3>4.4 Quy Trình Xử Lý Ngắt CanIf_ControllerBusOff() &amp; Phối Hợp CanSM</h3>\n  <p>Khi bộ đếm Transmit Error Counter (TEC) vượt quá 255 (do chập dây CAN_H/CAN_L hoặc nhiễu nặng), phần cứng tự động ngắt khỏi bus và kích hoạt ngắt <code>CanIf_ControllerBusOff(ControllerId)</code>:</p>\n  <ol>\n    <li><b>Cập nhật trạng thái:</b> CanIf đưa ngay <code>ControllerMode = CAN_CS_STOPPED</code> (khớp hành vi phần cứng M_CAN/FlexCAN tự vào Init/Stop mode).</li>\n    <li><b>Khóa cổng phát:</b> Chuyển <code>PduMode = CANIF_TX_OFFLINE</code> nhằm chặn mọi yêu cầu phát mới từ Com/PduR trong thời gian hồi phục.</li>\n    <li><b>Dọn sạch bộ đệm:</b> Xóa sạch toàn bộ L-PDU tồn đọng trong <code>CanIfTxBuffer</code> tránh việc khi phục hồi lại bus lại bắn ra hàng loạt tin cũ lỗi thời!</li>\n    <li><b>Báo CanSM:</b> Reset <code>TxConfirmationState = CANIF_NO_NOTIFICATION</code> và gọi <code>CanSM_ControllerBusOff()</code> để CanSM chạy chiến lược hồi phục (BOR L1 Fast Recovery → L2 Slow Recovery).</li>\n  </ol>\n</div>"
      }
    ]
  },
  {
    "title": "5. Wakeup Validation & CanTrcv",
    "subs": [
      {
        "title": "5.1 Chu Trình Đánh Thức 2 Pha Chống Nhiễu",
        "html": "\n<div class=\"hb-card\">\n  <h3>5.1 Wakeup Validation: Phân Biệt Khung CAN Thật Với Nhiễu ESD (Glitch)</h3>\n  <p>Nếu chỉ dựa vào một xung cạnh xuống trên chân CAN_RX để đánh thức toàn bộ hệ thống xe, ECU có thể bị bật sáng liên tục ban đêm bởi nhiễu điện từ trường gây sụt ắc quy. Do đó AUTOSAR thiết kế cơ chế xác thực 2 pha qua <code>CanIf</code> và <code>EcuM</code>:</p>\n  <svg class=\"hb-svg\" viewBox=\"0 0 820 172\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"hbArr\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"currentColor\" /></marker></defs><rect x=\"18\" y=\"30\" width=\"145\" height=\"64\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--pur)\" stroke-width=\"1.6\" /><text x=\"90.5\" y=\"58.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">1. HW Wakeup</text><text x=\"90.5\" y=\"74.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">CanTrcv WUF / INH</text><rect x=\"192\" y=\"30\" width=\"162\" height=\"64\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--warn)\" stroke-width=\"1.6\" /><text x=\"273.0\" y=\"50.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">2. CheckWakeup()</text><text x=\"273.0\" y=\"66.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">EcuM_SetWakeupEvt</text><text x=\"273.0\" y=\"82.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">(Chưa Validate!)</text><rect x=\"386\" y=\"30\" width=\"178\" height=\"64\" rx=\"8\" fill=\"var(--panel-2)\" stroke=\"var(--cyan)\" stroke-width=\"1.6\" /><text x=\"475.0\" y=\"50.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">3. RxIndication()</text><text x=\"475.0\" y=\"66.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">Chờ &gt;=1 khung hợp lệ</text><text x=\"475.0\" y=\"82.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">(Hoặc chỉ CanNm)</text><rect x=\"596\" y=\"30\" width=\"206\" height=\"64\" rx=\"8\" fill=\"var(--ok-bg)\" stroke=\"var(--ok)\" stroke-width=\"1.6\" /><text x=\"699.0\" y=\"50.0\" text-anchor=\"middle\" fill=\"var(--pri)\" font-size=\"12\" font-weight=\"800\">4. CheckValidation()</text><text x=\"699.0\" y=\"66.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">EcuM_ValidateWakeupEvt()</text><text x=\"699.0\" y=\"82.0\" text-anchor=\"middle\" fill=\"var(--txt-soft)\" font-size=\"10\" font-weight=\"500\">ECU giữ FullCom!</text><line x1=\"163\" y1=\"62\" x2=\"192\" y2=\"62\" stroke=\"var(--pur)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--pur)\" /><line x1=\"354\" y1=\"62\" x2=\"386\" y2=\"62\" stroke=\"var(--warn)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--warn)\" /><line x1=\"564\" y1=\"62\" x2=\"596\" y2=\"62\" stroke=\"var(--ok)\" stroke-width=\"1.8\" marker-end=\"url(#hbArr)\" style=\"color:var(--ok)\" /><rect x=\"110\" y=\"122\" width=\"600\" height=\"32\" rx=\"10\" fill=\"var(--warn-bg)\" stroke=\"var(--warn)\" stroke-width=\"1.2\" /><text x=\"410.0\" y=\"141.5\" text-anchor=\"middle\" fill=\"var(--warn)\" font-size=\"10\" font-weight=\"700\">Nếu hết timer mà KHÔNG nhận được Rx hợp lệ -&gt; Coi là nhiễu Glitch ESD -&gt; ECU GoSleep!</text></svg>\n  <ul>\n    <li><b>Pha 1 — <code>CanIf_CheckWakeup(WakeupSource)</code> (SWS_CanIf_00219):</b> Kiểm tra nguyên nhân đánh thức ở phần cứng Controller hoặc Transceiver. Nếu có cờ, gọi <code>EcuM_SetWakeupEvent()</code> nhưng <b>CHƯA xác nhận hợp lệ</b>.</li>\n    <li><b>Pha 2 — <code>CanIf_CheckValidation(WakeupSource)</code> (SWS_CanIf_00178):</b> EcuM chỉ giữ ECU ở chế độ hoạt động nếu trong cửa sổ timeout đã thực sự nhận được ít nhất 1 khung <code>CanIf_RxIndication()</code> vượt qua bộ lọc + DLC Check! Có thể siết chặt hơn bằng <code>CanIfWakeupCheckValidByNM = TRUE</code> (chỉ tin khung từ <code>CanNm</code>).</li>\n  </ul>\n</div>"
      },
      {
        "title": "5.2 Điều Khiển CanTrcv & Cờ WUF",
        "html": "\n<div class=\"hb-card\">\n  <h3>5.2 Giao Tiếp Giữa CanIf Và CAN Transceiver (TJA1043 / TJA1145)</h3>\n  <p>Trong xe hiện đại, ECU có thể dùng Transceiver thông minh giao tiếp SPI hỗ trợ Selective Wakeup:</p>\n  <table class=\"tbl\">\n    <tr><th>API CanIf</th><th>Chuyển Xuống CanTrcv</th><th>Mục Đích Vận Hành</th></tr>\n    <tr><td class=\"mono\">CanIf_SetTrcvMode()</td><td class=\"mono\">CanTrcv_SetOpMode()</td><td>Chuyển bộ thu phát qua <code>NORMAL</code>, <code>STANDBY</code> hoặc <code>SLEEP</code> (ngắt nguồn Vreg tiết kiệm uA).</td></tr>\n    <tr><td class=\"mono\">CanIf_GetTrcvMode()</td><td class=\"mono\">CanTrcv_GetOpMode()</td><td>Đọc lại chế độ thực tế hiện tại của IC Transceiver.</td></tr>\n    <tr><td class=\"mono\">CanIf_ClearTrcvWufFlag()</td><td class=\"mono\">CanTrcv_ClearTrcvWufFlag()</td><td>Xóa cờ Wake-Up Flag (WUF) trong thanh ghi Transceiver trước khi ECU tiến hành GoSleep lần kế tiếp.</td></tr>\n    <tr><td class=\"mono\">CanIf_CheckTrcvWakeFlag()</td><td class=\"mono\">CanTrcv_CheckWakeFlag()</td><td>Kiểm tra lại cờ WUF sau khi cấu hình Partial Networking.</td></tr>\n  </table>\n</div>"
      },
      {
        "title": "5.3 Wakeup By NM vs Any Valid Frame",
        "html": "\n<div class=\"hb-card\">\n  <h3>5.3 Lựa Chọn CanIfWakeupCheckValidByNM Theo Chiến Lược OEM</h3>\n  <div class=\"hb-grid2\">\n    <div>\n      <h4>CanIfWakeupCheckValidByNM = FALSE</h4>\n      <p>Bất kỳ RxPdu hợp lệ nào (Application COM Frame hoặc Diagnostic UDS Request 0x7E0) đến sau khi Controller vừa chuyển sang <code>CAN_CS_STARTED</code> đều đánh dấu cờ xác thực Wakeup hợp lệ.</p>\n    </div>\n    <div>\n      <h4>CanIfWakeupCheckValidByNM = TRUE</h4>\n      <p>Siết chặt kỷ luật: Chỉ những bản tin có <code>UpperLayer == CANNM</code> (hoặc <code>CanIfRxPduUserRxIndicationUL = CANNM</code>) mới được công nhận. Các khung ứng dụng lạc nhịp trước khi mạng khởi động sẽ không đánh lừa được <code>EcuM_ValidateWakeupEvent()</code>.</p>\n    </div>\n  </div>\n</div>"
      },
      {
        "title": "5.4 Trạng Thái GoSleep & Phối Hợp Tắt Mạng",
        "html": "\n<div class=\"hb-card\">\n  <h3>5.4 Thứ Tự Đưa Hệ Thống CAN Về Ngủ An Toàn</h3>\n  <ol>\n    <li><code>ComM</code> hết yêu cầu → <code>CanNm</code> hết timer → <code>CanSM</code> bắt đầu chuỗi De-init truyền thông.</li>\n    <li><code>CanSM</code> gọi <code>CanIf_SetPduMode(0, CANIF_OFFLINE)</code> khóa lưu lượng PDU.</li>\n    <li><code>CanSM</code> gọi <code>CanIf_SetControllerMode(0, CAN_CS_STOPPED)</code> rồi tiếp tục <code>CAN_CS_SLEEP</code>.</li>\n    <li><code>CanIf_ClearTrcvWufFlag(0)</code> xóa sạch cờ cũ, cuối cùng gọi <code>CanIf_SetTrcvMode(0, STANDBY/SLEEP)</code>.</li>\n  </ol>\n</div>"
      }
    ]
  },
  {
    "title": "6. API R23-11, ECUC, DET & Thực Chiến",
    "subs": [
      {
        "title": "6.1 Danh Mục API Chuẩn AUTOSAR R23-11",
        "html": "\n<div class=\"hb-card\">\n  <h3>6.1 Bảng Tra Cứu Nhanh Service ID &amp; API Chuẩn SWS_CanIf</h3>\n  <table class=\"tbl\">\n    <tr><th>API Name (AUTOSAR R23-11)</th><th>SID</th><th>Ngữ Cảnh Gọi</th><th>Input ➔ Output</th></tr>\n    <tr><td class=\"mono\">CanIf_Init()</td><td class=\"mono\">0x01</td><td>Startup Task (EcuM)</td><td>Post-Build Ptr ➔ Khởi tạo biến nội bộ &amp; Ctrl về STOPPED.</td></tr>\n    <tr><td class=\"mono\">CanIf_SetControllerMode()</td><td class=\"mono\">0x03</td><td>CanSM State Machine</td><td>ControllerId, Mode ➔ <code>Can_SetControllerMode()</code>.</td></tr>\n    <tr><td class=\"mono\">CanIf_SetPduMode()</td><td class=\"mono\">0x09</td><td>CanSM / BswM</td><td>ControllerId, PduModeReq ➔ Đóng/mở cổng Tx/Rx.</td></tr>\n    <tr><td class=\"mono\">CanIf_SetDynamicTxId()</td><td class=\"mono\">0x0C</td><td>J1939Nm / CDD</td><td>TxPduId, NewCanId ➔ Cập nhật CAN ID động trong RAM.</td></tr>\n    <tr><td class=\"mono\">CanIf_CheckWakeup()</td><td class=\"mono\">0x11</td><td>EcuM Wakeup Poll</td><td>WakeupSource ➔ Kiểm tra cờ HW WUF &amp; báo EcuM.</td></tr>\n    <tr><td class=\"mono\">CanIf_CheckValidation()</td><td class=\"mono\">0x12</td><td>EcuM Validation</td><td>WakeupSource ➔ Kiểm tra đã thấy Rx hợp lệ chưa.</td></tr>\n    <tr><td class=\"mono\">CanIf_TxConfirmation()</td><td class=\"mono\">0x13</td><td>CanDrv TX ISR</td><td>CanTxPduId ➔ Báo Upper Layer &amp; xả tiếp CanIfTxBuffer.</td></tr>\n    <tr><td class=\"mono\">CanIf_RxIndication()</td><td class=\"mono\">0x14</td><td>CanDrv RX ISR</td><td>Mailbox, PduInfo ➔ SwFilter + DLC Check ➔ UL Callback.</td></tr>\n    <tr><td class=\"mono\">CanIf_ControllerBusOff()</td><td class=\"mono\">0x16</td><td>CanDrv Err ISR</td><td>ControllerId ➔ STOPPED + TX_OFFLINE + ClearBuf ➔ CanSM.</td></tr>\n    <tr><td class=\"mono\">CanIf_SetBaudrate()</td><td class=\"mono\">0x27</td><td>CanSM / ComM / BswM</td><td>ControllerId, BaudId ➔ Chuyển tiếp <code>Can_SetBaudrate()</code>.</td></tr>\n    <tr><td class=\"mono\">CanIf_TriggerTransmit()</td><td class=\"mono\">0x41</td><td>CanDrv Tx Pre-load</td><td>TxPduId, PduInfoPtr ➔ Kéo payload tức thời từ PduR.</td></tr>\n    <tr><td class=\"mono\">CanIf_Transmit()</td><td class=\"mono\">0x49</td><td>PduR / CanTp / CanNm</td><td>TxPduId, PduInfoPtr ➔ <code>Can_Write()</code> hoặc TxBuffer.</td></tr>\n  </table>\n</div>"
      },
      {
        "title": "6.2 Ma Trận Lỗi DET & Runtime Errors (Mod 60)",
        "html": "\n<div class=\"hb-card\">\n  <h3>6.2 Hàng Rào Bắt Lỗi Development Error (DET) &amp; Runtime Errors</h3>\n  <table class=\"tbl\">\n    <tr><th>Mã Lỗi</th><th>Loại</th><th>Hex</th><th>Nguyên Nhân &amp; Cách Khắc Phục Nhanh</th></tr>\n    <tr><td class=\"mono\">CANIF_E_PARAM_CANID</td><td>DET</td><td class=\"mono\">0x0A</td><td>Giá trị <code>CanId</code> vượt biên (Standard &gt; 0x7FF hoặc Extended &gt; 0x1FFFFFFF).</td></tr>\n    <tr><td class=\"mono\">CANIF_E_PARAM_CTRLMODE</td><td>DET</td><td class=\"mono\">0x0D</td><td>Yêu cầu chuyển trạng thái Controller không hợp lệ (VD: STARTED ➔ SLEEP trực tiếp).</td></tr>\n    <tr><td class=\"mono\">CANIF_E_PARAM_CONTROLLERID</td><td>DET</td><td class=\"mono\">0x0F</td><td>ControllerId truyền vào lớn hơn hoặc bằng số controller cấu hình.</td></tr>\n    <tr><td class=\"mono\">CANIF_E_UNINIT</td><td>DET</td><td class=\"mono\">0x1E</td><td>Gọi API trước khi hoàn tất <code>CanIf_Init()</code>.</td></tr>\n    <tr><td class=\"mono\">CANIF_E_INVALID_TXPDUID</td><td>DET</td><td class=\"mono\">0x32</td><td>TxPduId ngoài bảng <code>CanIfTxPduCfg</code>. Kiểm tra lại file ghép nối PduR ↔ CanIf ARXML!</td></tr>\n    <tr><td class=\"mono\">CANIF_E_INVALID_DATA_LENGTH</td><td>Runtime</td><td class=\"mono\">0x32</td><td>Rx DLC thực tế ngắn hơn <code>CanIfRxPduDataLength</code> cấu hình. Khung bị hủy bảo vệ bộ nhớ.</td></tr>\n    <tr><td class=\"mono\">CANIF_E_TXPDU_LENGTH_EXCEEDED</td><td>Runtime</td><td class=\"mono\">0x33</td><td>Tx SduLength vượt 8B (CAN 2.0) hoặc 64B (CAN FD). Kiểm tra <code>CanIfTxPduTruncation</code>.</td></tr>\n  </table>\n</div>"
      },
      {
        "title": "6.3 Checklist Debug CanIf Thực Chiến Trên Bench",
        "html": "\n<div class=\"hb-card\">\n  <h3>6.3 6 Lỗi Thực Chiến Hay Gặp Nhất Khi Tích Hợp CanIf Stack</h3>\n  <ol>\n    <li><b>Gọi CanIf_Transmit() trả về E_OK nhưng không thấy frame lên Bus:</b> Kiểm tra ngay xem <code>PduMode</code> có đang ở <code>CANIF_TX_OFFLINE_ACTIVE</code> (bắn TxConfirm ảo!) hoặc bản tin bị giữ trong <code>CanIfTxBuffer</code> do HTH kẹt BUSY.</li>\n    <li><b>Bus có sóng CAN nhưng PduR không nhận được:</b> Kiểm tra lần lượt: (a) <code>ControllerMode == CAN_CS_STARTED</code>? (b) <code>PduMode != CANIF_OFFLINE</code>? (c) Mask của BasicCAN HRH có khớp ID chưa? (d) Có bị rớt tại <code>DLC Check 0x32</code> vì sender gửi 7 byte trong khi Min DLC đặt 8 byte?</li>\n    <li><b>Lệch Extended vs Standard CAN ID:</b> Nhớ cộng <code>0x80000000</code> (Bit 31) và <code>0x40000000</code> (Bit 30 FD) khi kiểm tra bảng cấu hình ARXML ➔ C.</li>\n    <li><b>Mất tin ưu tiên thấp hoặc kẹt CAN_BUSY:</b> Tăng <code>CanIfTxBufferSize</code> hoặc tách các khung tần suất cao sang FullCAN HTH riêng.</li>\n    <li><b>ECU tự động thức dậy liên tục rồi ngủ lại:</b> Bật <code>CanIfPublicWakeupCheckValidSupport</code> và xem nhật ký có Rx hợp lệ nào đến trước khi hết timer EcuM không.</li>\n    <li><b>Xử lý Bus-Off làm treo Com:</b> Phải đảm bảo <code>CanSM</code> lắng nghe được <code>CanIf_ControllerBusOff()</code> và gọi lại đúng trình tự <code>STOPPED ➔ STARTED ➔ ONLINE</code>.</li>\n  </ol>\n</div>"
      },
      {
        "title": "6.4 Hướng Dẫn Xuất ARXML / Cfg.h / Lcfg.c Sang DaVinci / Tresos",
        "html": "\n<div class=\"hb-card\">\n  <h3>6.4 Áp Dụng Kết Quả Simulator Vào Công Cụ Cấu Hình Thực Tế</h3>\n  <ul>\n    <li>Sau khi tinh chỉnh 36 tham số ECUC ở bảng bên trái (như <code>CanIfPublicTxBuffering</code>, <code>CanIfPrivateSoftwareFilterType</code>, <code>CanIfPrivateDlcCheck</code>, <code>CanIfTxPduTruncation</code>...), hãy bấm nút <b>📦 Xuất ARXML / Cfg / C</b> trên thanh header.</li>\n    <li>Tab <b>CanIf.arxml</b> xuất đúng phân cấp container <code>/AUTOSAR/EcucDefs/CanIf/CanIfPublicCfg</code> &amp; <code>CanIfPrivateCfg</code> tương thích Vector DaVinci Configurator &amp; EB Tresos.</li>\n    <li>Tab <b>CanIf_Cfg.h</b> &amp; <b>CanIf_Lcfg.c</b> cung cấp mã C trực tiếp để đối chiếu macro biên dịch và bảng định tuyến callback từng PDU.</li>\n  </ul>\n</div>"
      }
    ]
  }
];

let hbState = {
  tab1: 0,
  subTab: [0, 0, 0, 0, 0, 0],
  abbrCat: "ALL"
};

function switchHbTab1(idx) {
  hbState.tab1 = idx;
  for (let i = 0; i < 7; i++) {
    const b = document.getElementById("hbTab1_" + i);
    if (b) b.classList.toggle("active", i === idx);
  }
  renderCurrentHandbookView();
}

function switchHbSubTab(subIdx) {
  hbState.subTab[hbState.tab1] = subIdx;
  renderCurrentHandbookView();
}

function setAbbrCategory(cat) {
  hbState.abbrCat = cat || "ALL";
  const allCats = ["ALL", "CORE", "TX", "RX", "MODE", "API"];
  allCats.forEach(c => {
    const el = document.getElementById("catPill_" + c);
    if (el) el.classList.toggle("active", c === hbState.abbrCat);
  });
  filterAbbreviationTable();
}

function highlightMatch(text, query) {
  const safeText = escHtml(text);
  const q = (query || "").trim();
  if (!q) return safeText;
  const escaped = q.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const re = new RegExp("(" + escaped + ")", "ig");
  return safeText.replace(re, "<mark>$1</mark>");
}

function renderAbbreviationTable(query) {
  const q = (query || "").trim().toLowerCase();
  const cat = hbState.abbrCat;
  const filtered = ABBREVIATIONS.filter(item => {
    if (cat !== "ALL" && item.cat !== cat) return false;
    if (!q) return true;
    const hay = (item.abbr + " " + item.full + " " + item.meaning + " " + item.cat).toLowerCase();
    return hay.indexOf(q) >= 0;
  });

  const badge = document.getElementById("abbrCountBadge");
  if (badge) badge.textContent = filtered.length + " / " + ABBREVIATIONS.length + " thuật ngữ";

  const area = document.getElementById("hbContentArea");
  if (!area) return;
  if (!filtered.length) {
    area.innerHTML = "<div class='hb-card'><p>Không tìm thấy thuật ngữ nào khớp từ khóa <b>" + escHtml(query) + "</b>. Hãy thử tìm: <code>HOH</code>, <code>BasicCAN</code>, <code>TxBuffer</code>, <code>0x32</code>, <code>WUF</code>...</p></div>";
    return;
  }

  const catLabels = { CORE: "CanIf Core", TX: "Tx & Buffer", RX: "Rx & CAN-FD", MODE: "Mode & Wakeup", API: "API & DET" };
  const rows = filtered.map(item =>
    "<tr>" +
    "  <td class='mono' style='font-weight:800;color:var(--pri);white-space:nowrap'>" + highlightMatch(item.abbr, query) + "</td>" +
    "  <td style='font-weight:700'>" + highlightMatch(item.full, query) + "</td>" +
    "  <td><span class='pill pill-cyan'>" + escHtml(catLabels[item.cat] || item.cat) + "</span></td>" +
    "  <td>" + highlightMatch(item.meaning, query) + "</td>" +
    "</tr>"
  ).join("");

  area.innerHTML =
    "<div class='hb-card'>" +
    "  <h3>7. Bảng Thuật Ngữ &amp; Viết Tắt AUTOSAR CanIf (" + filtered.length + " mục)</h3>" +
    "  <table class='tbl'>" +
    "    <thead><tr><th>Thuật Ngữ</th><th>Tên Đầy Đủ Tiếng Anh</th><th>Phân Nhóm</th><th>Giải Nghĩa &amp; Vai Trò Trong CanIf</th></tr></thead>" +
    "    <tbody>" + rows + "</tbody>" +
    "  </table>" +
    "</div>";
}

function filterAbbreviationTable() {
  const inp = document.getElementById("abbrSearchInput");
  renderAbbreviationTable(inp ? inp.value : "");
}

function renderCurrentHandbookView() {
  const nav2 = document.getElementById("hbNav2");
  const filterBox = document.getElementById("hbAbbrFilterBox");
  const area = document.getElementById("hbContentArea");

  if (hbState.tab1 === 6) {
    if (nav2) nav2.classList.add("hidden");
    if (filterBox) filterBox.classList.remove("hidden");
    filterAbbreviationTable();
    return;
  }

  if (filterBox) filterBox.classList.add("hidden");
  const tabData = HANDBOOK_TABS[hbState.tab1] || HANDBOOK_TABS[0];
  const activeSubIdx = hbState.subTab[hbState.tab1] || 0;

  if (nav2) {
    nav2.classList.remove("hidden");
    nav2.innerHTML = tabData.subs.map((s, idx) =>
      "<button class='hb-tab2 " + (idx === activeSubIdx ? "active" : "") + "' onclick='switchHbSubTab(" + idx + ")'>" + escHtml(s.title) + "</button>"
    ).join("");
  }

  if (area) {
    const subObj = tabData.subs[activeSubIdx] || tabData.subs[0];
    area.innerHTML = subObj.html;
  }
}

document.addEventListener("DOMContentLoaded", () => {
  initTooltipHandlers();
  switchCfgTab(0);
  onFaultKindChange();
  loadScenario("S1");
  renderCurrentHandbookView();
});
